def parse_nested_parens(paren_string: str) -> List[int]:
    def nested_level(group):
        max_level = current_level = 0
        for char in group:
            if char == '(':
                current_level += 1
                max_level = max(max_level, current_level)
            elif char == ')':
                current_level -= 1
        return max_level

    groups = paren_string.split()
    result = []
    for group in groups:
        result.append(nested_level(group))
    return result

# Example usage:
