def factorize(n: int) -> List[int]:
    factors = []
    # Start with the smallest prime factor
    divisor = 2
    while n > 1:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1
        # Check if divisor exceeds sqrt(n) to limit iterations
        if divisor * divisor > n:
            if n > 1:
                factors.append(n)
            break
    return factors

