        sum_digits = 0
        abs_num = abs(num)
        while abs_num > 0:
            sum_digits += (abs_num % 10) * (1 if num >= 0 else -1)
            abs_num //= 10
        return sum_digits

    count = 0
    for num in arr:
        if sum_of_digits(num) > 0:
            count += 1
    return count
