    in ascending order. If list has more than 1 duplicate of the same
    number, return False. Assume no negative numbers and only integers.
    '''
    # Check if the list is empty or only contains one element
    if len(lst) <= 1:
        return True

    # Create a copy of the list to track duplicates
    seen = set()
    for num in lst:
        if num in seen:
            return False
        seen.add(num)

    # Check if the list is sorted in ascending order
    for i in range(len(lst) - 1):
        if lst[i] > lst[i + 1]:
            return False
    return True

