def get_max_triples(n):
    a = [i * i - i + 1 for i in range(1, n + 1)]
    counter = Counter(x % 3 for x in a)
    count = 0

    # Calculate the number of triples (i, j, k) where i < j < k and a[i] + a[j] + a[k] is a multiple of 3
    for x in range(3):
        for y in range(x, 3):
            z = (3 - x - y) % 3
            if x == y and y == z and counter[z] >= 3:
                count += (counter[z] * (counter[z] - 1) * (counter[z] - 2)) // 6
            elif x == y!= z:
                count += counter[x] * counter[y] * counter[z]
            elif x!= y!= z:
                count += counter[x] * counter[y] * counter[z]

    return count
