def Strongest_Extension(class_name, extensions):
    def strength(extension):
        upper, lower = 0, 0
        for char in extension:
            if char.isupper():
                upper += 1
            elif char.islower():
                lower += 1
        return upper - lower

    strongest_extension = max(extensions, key=strength, default='')
    return f"{class_name}.{strongest_extension}" if strongest_extension else class_name
